INSERT INTO public.exercises (id,name,body_part,equipment,target,secondary_muscles,instructions,description,difficulty,category) VALUES
('pilates-roll-up','Roll-Up','waist','body weight','abs',ARRAY['hip flexors','spine']::text[],ARRAY['Lie supine with legs long, arms reaching overhead.','Set the breath and brace lightly before the first repetition.','Peel the spine off the mat one vertebra at a time, reach past the toes, then roll down with the same control.','Keep the ribs knitted down and never throw the arms to gain momentum.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Roll-Up is a pilates exercise for the abs with support from the hip flexors and spine. Lie supine with legs long, arms reaching overhead. Peel the spine off the mat one vertebra at a time, reach past the toes, then roll down with the same control. Keep the ribs knitted down and never throw the arms to gain momentum.','intermediate','pilates'),
('pilates-roll-over','Roll-Over','waist','body weight','abs',ARRAY['glutes','hamstrings']::text[],ARRAY['Lie supine with legs extended to the ceiling, arms pressed into the mat.','Set the breath and brace lightly before the first repetition.','Lift the hips and take the legs overhead parallel to the floor, open them hip width and roll down through each vertebra.','Press the arms down for support and never load the neck.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Roll-Over is a pilates exercise for the abs with support from the glutes and hamstrings. Lie supine with legs extended to the ceiling, arms pressed into the mat. Lift the hips and take the legs overhead parallel to the floor, open them hip width and roll down through each vertebra. Press the arms down for support and never load the neck.','advanced','pilates'),
('pilates-single-leg-circle','Single Leg Circle','upper legs','body weight','hip flexors',ARRAY['abs','adductors']::text[],ARRAY['Lie supine with one leg extended to the ceiling and the other long on the mat.','Set the breath and brace lightly before the first repetition.','Draw controlled circles with the raised leg, crossing the midline then opening, keeping the pelvis completely still.','The pelvis is the anchor: if it rocks, make the circle smaller.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Single Leg Circle is a pilates exercise for the hip flexors with support from the abs and adductors. Lie supine with one leg extended to the ceiling and the other long on the mat. Draw controlled circles with the raised leg, crossing the midline then opening, keeping the pelvis completely still. The pelvis is the anchor: if it rocks, make the circle smaller.','beginner','pilates'),
('pilates-rolling-like-a-ball','Rolling Like a Ball','waist','body weight','abs',ARRAY['spine','hip flexors']::text[],ARRAY['Sit balanced behind the sit bones, knees drawn in, hands on the shins.','Set the breath and brace lightly before the first repetition.','Roll back to the shoulder blades on an inhale and return to balance on an exhale without letting the feet touch down.','Keep the C-curve fixed; the shape never changes as you roll.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Rolling Like a Ball is a pilates exercise for the abs with support from the spine and hip flexors. Sit balanced behind the sit bones, knees drawn in, hands on the shins. Roll back to the shoulder blades on an inhale and return to balance on an exhale without letting the feet touch down. Keep the C-curve fixed; the shape never changes as you roll.','intermediate','pilates'),
('pilates-single-leg-stretch','Single Leg Stretch','waist','body weight','abs',ARRAY['hip flexors']::text[],ARRAY['Lie supine in chest lift with both knees drawn in.','Set the breath and brace lightly before the first repetition.','Extend one leg long at forty-five degrees while holding the other knee, then switch with control.','Keep the lower back printed into the mat and the chest lifted throughout.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Single Leg Stretch is a pilates exercise for the abs with support from the hip flexors. Lie supine in chest lift with both knees drawn in. Extend one leg long at forty-five degrees while holding the other knee, then switch with control. Keep the lower back printed into the mat and the chest lifted throughout.','beginner','pilates'),
('pilates-double-leg-stretch','Double Leg Stretch','waist','body weight','abs',ARRAY['hip flexors','shoulders']::text[],ARRAY['Lie supine in chest lift with both knees drawn in and hands on the ankles.','Set the breath and brace lightly before the first repetition.','Reach arms and legs long in opposite directions, then circle the arms and rehug the knees.','Only extend as low as you can keep the spine imprinted.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Double Leg Stretch is a pilates exercise for the abs with support from the hip flexors and shoulders. Lie supine in chest lift with both knees drawn in and hands on the ankles. Reach arms and legs long in opposite directions, then circle the arms and rehug the knees. Only extend as low as you can keep the spine imprinted.','intermediate','pilates'),
('pilates-spine-stretch-forward','Spine Stretch Forward','back','body weight','spine',ARRAY['hamstrings','abs']::text[],ARRAY['Sit tall with legs extended a little wider than the hips, arms reaching forward.','Set the breath and brace lightly before the first repetition.','Exhale and articulate the spine forward into a C-curve over the legs, then restack vertebra by vertebra.','Grow taller as you return rather than collapsing back.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Spine Stretch Forward is a pilates exercise for the spine with support from the hamstrings and abs. Sit tall with legs extended a little wider than the hips, arms reaching forward. Exhale and articulate the spine forward into a C-curve over the legs, then restack vertebra by vertebra. Grow taller as you return rather than collapsing back.','beginner','pilates'),
('pilates-open-leg-rocker','Open Leg Rocker','waist','body weight','abs',ARRAY['hamstrings','spine']::text[],ARRAY['Balance behind the sit bones holding the ankles with the legs open and straight.','Set the breath and brace lightly before the first repetition.','Roll back to the shoulder blades and return to balance without losing the leg position.','Control the return with the abdominals, never momentum.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Open Leg Rocker is a pilates exercise for the abs with support from the hamstrings and spine. Balance behind the sit bones holding the ankles with the legs open and straight. Roll back to the shoulder blades and return to balance without losing the leg position. Control the return with the abdominals, never momentum.','advanced','pilates'),
('pilates-corkscrew','Corkscrew','waist','body weight','abs',ARRAY['obliques','hip flexors']::text[],ARRAY['Lie supine with legs extended to the ceiling and arms pressed down.','Set the breath and brace lightly before the first repetition.','Circle both legs to one side, down through the centre and up the other side, then reverse.','Keep both shoulders glued to the mat and the ribs closed.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Corkscrew is a pilates exercise for the abs with support from the obliques and hip flexors. Lie supine with legs extended to the ceiling and arms pressed down. Circle both legs to one side, down through the centre and up the other side, then reverse. Keep both shoulders glued to the mat and the ribs closed.','advanced','pilates'),
('pilates-saw','Saw','waist','body weight','obliques',ARRAY['hamstrings','spine']::text[],ARRAY['Sit tall with legs wide and arms opened to the sides.','Set the breath and brace lightly before the first repetition.','Rotate the trunk and reach the opposite hand past the little toe, then restack and repeat to the other side.','Rotate from the waist and keep both sit bones heavy.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Saw is a pilates exercise for the obliques with support from the hamstrings and spine. Sit tall with legs wide and arms opened to the sides. Rotate the trunk and reach the opposite hand past the little toe, then restack and repeat to the other side. Rotate from the waist and keep both sit bones heavy.','beginner','pilates'),
('pilates-swan-dive','Swan Dive','back','body weight','spine',ARRAY['glutes','shoulders']::text[],ARRAY['Lie prone with hands under the shoulders and legs long.','Set the breath and brace lightly before the first repetition.','Press into a long spinal extension, then lower with control, keeping the neck in line with the spine.','Lengthen forward before lifting to avoid pinching the low back.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Swan Dive is a pilates exercise for the spine with support from the glutes and shoulders. Lie prone with hands under the shoulders and legs long. Press into a long spinal extension, then lower with control, keeping the neck in line with the spine. Lengthen forward before lifting to avoid pinching the low back.','intermediate','pilates'),
('pilates-single-leg-kick','Single Leg Kick','upper legs','body weight','hamstrings',ARRAY['glutes','spine']::text[],ARRAY['Lie prone propped on the forearms with elbows under the shoulders.','Set the breath and brace lightly before the first repetition.','Pulse one heel twice towards the glute, then switch legs with control.','Keep the pubic bone heavy so the low back stays long.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Single Leg Kick is a pilates exercise for the hamstrings with support from the glutes and spine. Lie prone propped on the forearms with elbows under the shoulders. Pulse one heel twice towards the glute, then switch legs with control. Keep the pubic bone heavy so the low back stays long.','beginner','pilates'),
('pilates-double-leg-kick','Double Leg Kick','back','body weight','spine',ARRAY['hamstrings','chest']::text[],ARRAY['Lie prone with the head turned to one side and hands clasped on the low back.','Set the breath and brace lightly before the first repetition.','Kick both heels to the glutes three times, then extend the arms back and lift into extension.','Move slowly and keep the shoulders away from the ears.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Double Leg Kick is a pilates exercise for the spine with support from the hamstrings and chest. Lie prone with the head turned to one side and hands clasped on the low back. Kick both heels to the glutes three times, then extend the arms back and lift into extension. Move slowly and keep the shoulders away from the ears.','intermediate','pilates'),
('pilates-neck-pull','Neck Pull','waist','body weight','abs',ARRAY['spine','hip flexors']::text[],ARRAY['Lie supine with hands behind the head and legs long and hip width.','Set the breath and brace lightly before the first repetition.','Roll up through the spine, hinge tall over the legs, then roll back down one vertebra at a time.','Never pull on the neck; the hands only rest there.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Neck Pull is a pilates exercise for the abs with support from the spine and hip flexors. Lie supine with hands behind the head and legs long and hip width. Roll up through the spine, hinge tall over the legs, then roll back down one vertebra at a time. Never pull on the neck; the hands only rest there.','advanced','pilates'),
('pilates-scissors','Scissors','waist','body weight','abs',ARRAY['hamstrings','hip flexors']::text[],ARRAY['Lie supine in chest lift with both legs to the ceiling.','Set the breath and brace lightly before the first repetition.','Split the legs and pulse the top leg towards you twice, then switch in a scissor rhythm.','Keep the pelvis level and the reaching leg long.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Scissors is a pilates exercise for the abs with support from the hamstrings and hip flexors. Lie supine in chest lift with both legs to the ceiling. Split the legs and pulse the top leg towards you twice, then switch in a scissor rhythm. Keep the pelvis level and the reaching leg long.','intermediate','pilates'),
('pilates-shoulder-bridge','Shoulder Bridge','upper legs','body weight','glutes',ARRAY['hamstrings','abs']::text[],ARRAY['Lie supine with knees bent, feet hip width and arms long by the sides.','Set the breath and brace lightly before the first repetition.','Articulate the hips up to a straight line, optionally extend one leg, then roll down through the spine.','Press the feet down and lead with the pubic bone, not the ribs.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Shoulder Bridge is a pilates exercise for the glutes with support from the hamstrings and abs. Lie supine with knees bent, feet hip width and arms long by the sides. Articulate the hips up to a straight line, optionally extend one leg, then roll down through the spine. Press the feet down and lead with the pubic bone, not the ribs.','beginner','pilates'),
('pilates-spine-twist','Spine Twist Pilates','waist','body weight','obliques',ARRAY['spine']::text[],ARRAY['Sit tall with legs together and arms opened wide.','Set the breath and brace lightly before the first repetition.','Rotate the trunk with two small pulses, return to centre and repeat to the other side.','Grow taller on every rotation and keep the hips square.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Spine Twist Pilates is a pilates exercise for the obliques with support from the spine. Sit tall with legs together and arms opened wide. Rotate the trunk with two small pulses, return to centre and repeat to the other side. Grow taller on every rotation and keep the hips square.','beginner','pilates'),
('pilates-jackknife','Jackknife','waist','body weight','abs',ARRAY['glutes','spine']::text[],ARRAY['Lie supine with legs to the ceiling and arms pressed into the mat.','Set the breath and brace lightly before the first repetition.','Lift the hips and reach the legs to a diagonal above you, then roll down with total control.','Never drop out of the position; the descent is the exercise.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Jackknife is a pilates exercise for the abs with support from the glutes and spine. Lie supine with legs to the ceiling and arms pressed into the mat. Lift the hips and reach the legs to a diagonal above you, then roll down with total control. Never drop out of the position; the descent is the exercise.','advanced','pilates'),
('pilates-side-kick-front-back','Side Kick Front and Back','upper legs','body weight','glutes',ARRAY['abs','adductors']::text[],ARRAY['Lie on one side with the body in a long line, head supported.','Set the breath and brace lightly before the first repetition.','Swing the top leg forward with two pulses, then sweep it behind without moving the trunk.','The waist stays lifted and the pelvis never rolls.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Side Kick Front and Back is a pilates exercise for the glutes with support from the abs and adductors. Lie on one side with the body in a long line, head supported. Swing the top leg forward with two pulses, then sweep it behind without moving the trunk. The waist stays lifted and the pelvis never rolls.','beginner','pilates'),
('pilates-side-kick-circles','Side Kick Circles','upper legs','body weight','glutes',ARRAY['abs','hip flexors']::text[],ARRAY['Lie on one side with the top leg lifted to hip height.','Set the breath and brace lightly before the first repetition.','Draw small controlled circles in both directions with the top leg.','Keep the ribcage still and the movement purely from the hip.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Side Kick Circles is a pilates exercise for the glutes with support from the abs and hip flexors. Lie on one side with the top leg lifted to hip height. Draw small controlled circles in both directions with the top leg. Keep the ribcage still and the movement purely from the hip.','beginner','pilates'),
('pilates-teaser','Teaser','waist','body weight','abs',ARRAY['hip flexors','spine']::text[],ARRAY['Lie supine with legs at a diagonal and arms overhead.','Set the breath and brace lightly before the first repetition.','Roll up through the spine to balance in a V position, then roll down vertebra by vertebra.','Reach the arms parallel to the legs and keep the shape as you lower.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Teaser is a pilates exercise for the abs with support from the hip flexors and spine. Lie supine with legs at a diagonal and arms overhead. Roll up through the spine to balance in a V position, then roll down vertebra by vertebra. Reach the arms parallel to the legs and keep the shape as you lower.','advanced','pilates'),
('pilates-hip-twist','Hip Twist','waist','body weight','obliques',ARRAY['abs','hip flexors']::text[],ARRAY['Sit propped on the hands behind you with both legs lifted to a diagonal.','Set the breath and brace lightly before the first repetition.','Circle both legs in one direction, then reverse, keeping the trunk lifted.','The trunk stays absolutely still while the legs move.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Hip Twist is a pilates exercise for the obliques with support from the abs and hip flexors. Sit propped on the hands behind you with both legs lifted to a diagonal. Circle both legs in one direction, then reverse, keeping the trunk lifted. The trunk stays absolutely still while the legs move.','advanced','pilates'),
('pilates-swimming','Swimming','back','body weight','spine',ARRAY['glutes','shoulders']::text[],ARRAY['Lie prone with arms and legs extended long.','Set the breath and brace lightly before the first repetition.','Lift opposite arm and leg and beat them in a small fast rhythm while breathing steadily.','Reach long rather than high and keep the neck in line.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Swimming is a pilates exercise for the spine with support from the glutes and shoulders. Lie prone with arms and legs extended long. Lift opposite arm and leg and beat them in a small fast rhythm while breathing steadily. Reach long rather than high and keep the neck in line.','beginner','pilates'),
('pilates-leg-pull-front','Leg Pull Front','waist','body weight','abs',ARRAY['glutes','shoulders']::text[],ARRAY['Start in a long plank with shoulders over the wrists.','Set the breath and brace lightly before the first repetition.','Lift one leg without shifting the hips, lower it and change sides.','The hips stay square; no rocking to free the leg.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Leg Pull Front is a pilates exercise for the abs with support from the glutes and shoulders. Start in a long plank with shoulders over the wrists. Lift one leg without shifting the hips, lower it and change sides. The hips stay square; no rocking to free the leg.','intermediate','pilates'),
('pilates-leg-pull-back','Leg Pull Back','back','body weight','glutes',ARRAY['hamstrings','shoulders']::text[],ARRAY['Sit with legs long and hands behind the hips, then lift into a reverse plank.','Set the breath and brace lightly before the first repetition.','Lift one leg to the ceiling and lower it with control, then change sides.','Keep the chest open and the hips high throughout.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Leg Pull Back is a pilates exercise for the glutes with support from the hamstrings and shoulders. Sit with legs long and hands behind the hips, then lift into a reverse plank. Lift one leg to the ceiling and lower it with control, then change sides. Keep the chest open and the hips high throughout.','intermediate','pilates'),
('pilates-side-bend-mermaid','Side Bend Mermaid','waist','body weight','obliques',ARRAY['shoulders','spine']::text[],ARRAY['Sit on one hip with legs folded to the side and one hand planted.','Set the breath and brace lightly before the first repetition.','Press up into a side support and arc the top arm overhead, then lower with control.','Lengthen through the side waist instead of collapsing into the shoulder.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Side Bend Mermaid is a pilates exercise for the obliques with support from the shoulders and spine. Sit on one hip with legs folded to the side and one hand planted. Press up into a side support and arc the top arm overhead, then lower with control. Lengthen through the side waist instead of collapsing into the shoulder.','intermediate','pilates'),
('pilates-boomerang','Boomerang','waist','body weight','abs',ARRAY['hamstrings','spine']::text[],ARRAY['Sit tall with legs crossed and extended long in front.','Set the breath and brace lightly before the first repetition.','Roll back overhead, change the leg cross, roll up to a teaser and circle the arms behind.','Sequence the whole movement slowly with no pause or collapse.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Boomerang is a pilates exercise for the abs with support from the hamstrings and spine. Sit tall with legs crossed and extended long in front. Roll back overhead, change the leg cross, roll up to a teaser and circle the arms behind. Sequence the whole movement slowly with no pause or collapse.','advanced','pilates'),
('pilates-seal','Seal','waist','body weight','abs',ARRAY['spine','adductors']::text[],ARRAY['Balance behind the sit bones with the soles of the feet together and hands threaded under the knees.','Set the breath and brace lightly before the first repetition.','Clap the feet three times, roll back to the shoulder blades, clap again and return to balance.','Keep the same round shape from start to finish.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Seal is a pilates exercise for the abs with support from the spine and adductors. Balance behind the sit bones with the soles of the feet together and hands threaded under the knees. Clap the feet three times, roll back to the shoulder blades, clap again and return to balance. Keep the same round shape from start to finish.','beginner','pilates'),
('pilates-crab','Crab Pilates','waist','body weight','abs',ARRAY['spine']::text[],ARRAY['Sit holding crossed ankles with the knees drawn in tightly.','Set the breath and brace lightly before the first repetition.','Roll back to the shoulder blades and forward onto the crown of the head with complete control.','Only touch the head down if the neck is entirely comfortable.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Crab Pilates is a pilates exercise for the abs with support from the spine. Sit holding crossed ankles with the knees drawn in tightly. Roll back to the shoulder blades and forward onto the crown of the head with complete control. Only touch the head down if the neck is entirely comfortable.','advanced','pilates'),
('pilates-control-balance','Control Balance','waist','body weight','abs',ARRAY['glutes','hamstrings']::text[],ARRAY['Lie supine with legs extended to the ceiling and arms long.','Set the breath and brace lightly before the first repetition.','Take the legs overhead, hold one ankle and reach the other leg to the ceiling, then switch.','Support the weight on the shoulders, never the neck.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Control Balance is a pilates exercise for the abs with support from the glutes and hamstrings. Lie supine with legs extended to the ceiling and arms long. Take the legs overhead, hold one ankle and reach the other leg to the ceiling, then switch. Support the weight on the shoulders, never the neck.','advanced','pilates'),
('pilates-push-up','Pilates Push-Up','chest','body weight','pectorals',ARRAY['triceps','abs']::text[],ARRAY['Stand tall, then roll down and walk the hands out to a plank.','Set the breath and brace lightly before the first repetition.','Perform three controlled push-ups with the elbows close, then walk back and restack the spine.','Keep one long line from head to heels on every repetition.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Pilates Push-Up is a pilates exercise for the pectorals with support from the triceps and abs. Stand tall, then roll down and walk the hands out to a plank. Perform three controlled push-ups with the elbows close, then walk back and restack the spine. Keep one long line from head to heels on every repetition.','intermediate','pilates'),
('pilates-pelvic-curl','Pelvic Curl','upper legs','body weight','glutes',ARRAY['hamstrings','abs']::text[],ARRAY['Lie supine with knees bent and feet hip width.','Set the breath and brace lightly before the first repetition.','Tilt the pelvis, peel the spine off the mat to the shoulder blades, then melt down vertebra by vertebra.','Move slowly enough to feel every segment of the spine.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Pelvic Curl is a pilates exercise for the glutes with support from the hamstrings and abs. Lie supine with knees bent and feet hip width. Tilt the pelvis, peel the spine off the mat to the shoulder blades, then melt down vertebra by vertebra. Move slowly enough to feel every segment of the spine.','beginner','pilates'),
('pilates-chest-lift','Chest Lift','waist','body weight','abs',ARRAY['obliques']::text[],ARRAY['Lie supine with knees bent and hands cradling the head.','Set the breath and brace lightly before the first repetition.','Exhale and curl the head chest and shoulders up, then lower with control.','Curl from the ribs, not from the chin.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Chest Lift is a pilates exercise for the abs with support from the obliques. Lie supine with knees bent and hands cradling the head. Exhale and curl the head chest and shoulders up, then lower with control. Curl from the ribs, not from the chin.','beginner','pilates'),
('pilates-chest-lift-rotation','Chest Lift with Rotation','waist','body weight','obliques',ARRAY['abs']::text[],ARRAY['Lie supine in chest lift position with hands behind the head.','Set the breath and brace lightly before the first repetition.','Rotate the ribcage towards one knee, return to centre and repeat to the other side.','Rotate the whole ribcage rather than swinging the elbow.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Chest Lift with Rotation is a pilates exercise for the obliques with support from the abs. Lie supine in chest lift position with hands behind the head. Rotate the ribcage towards one knee, return to centre and repeat to the other side. Rotate the whole ribcage rather than swinging the elbow.','intermediate','pilates'),
('pilates-criss-cross','Criss-Cross','waist','body weight','obliques',ARRAY['abs','hip flexors']::text[],ARRAY['Lie supine in chest lift with both knees drawn in.','Set the breath and brace lightly before the first repetition.','Extend one leg and rotate the opposite shoulder towards the bent knee, then switch in a slow rhythm.','Hold each rotation for a breath instead of racing.','Keep the tempo controlled: never rush the return phase.','Complete the prescribed repetitions or time, then rest as written.']::text[],'Criss-Cross is a pilates exercise for the obliques with support from the abs and hip flexors. Lie supine in chest lift with both knees drawn in. Extend one leg and rotate the opposite shoulder towards the bent knee, then switch in a slow rhythm. Hold each rotation for a breath instead of racing.','intermediate','pilates')
